package com.example.data.model

import org.json.JSONObject

/**
 * QR payload generated by TechDesk DZ Windows settings interface.
 * Example: {"ref":"TDZ-A7K29M","code":"849201","ip":"192.168.1.10","port":3000}
 */
data class QrPayload(
    val ref: String,
    val code: String,
    val ip: String,
    val port: Int
) {
    companion object {
        fun parseJson(raw: String): Result<QrPayload> {
            return runCatching {
                val trimmed = raw.trim()
                if (!trimmed.startsWith("{") || !trimmed.endsWith("}")) {
                    throw IllegalArgumentException("Payload must be a JSON object")
                }

                var ref = ""
                var code = ""
                var ip = ""
                var port = 3000
                var portSpecified = false

                try {
                    val json = JSONObject(trimmed)
                    ref = json.optString("ref", "").trim()
                    code = json.optString("code", "").trim()
                    ip = json.optString("ip", "").trim()
                    if (json.has("port")) {
                        port = json.getInt("port")
                        portSpecified = true
                    }
                } catch (_: Throwable) {
                    // Fallback parser for JVM environments where android.jar JSONObject is stubbed
                }

                if (ref.isEmpty()) {
                    val refMatch = Regex("\"ref\"\\s*:\\s*\"([^\"]+)\"").find(trimmed)
                    ref = refMatch?.groupValues?.get(1)?.trim().orEmpty()
                }
                if (code.isEmpty()) {
                    val codeMatch = Regex("\"code\"\\s*:\\s*\"?([^\",\\s}]+)\"?").find(trimmed)
                    code = codeMatch?.groupValues?.get(1)?.trim().orEmpty()
                }
                if (ip.isEmpty()) {
                    val ipMatch = Regex("\"ip\"\\s*:\\s*\"([^\"]+)\"").find(trimmed)
                    ip = ipMatch?.groupValues?.get(1)?.trim().orEmpty()
                }
                if (!portSpecified) {
                    val portMatch = Regex("\"port\"\\s*:\\s*(-?\\d+)").find(trimmed)
                    if (portMatch != null) {
                        port = portMatch.groupValues[1].toIntOrNull() ?: 3000
                    }
                }

                if (ref.isEmpty()) {
                    throw IllegalArgumentException("Missing required 'ref' in QR payload")
                }
                if (code.isEmpty()) {
                    throw IllegalArgumentException("Missing required 'code' in QR payload")
                }
                if (ip.isEmpty()) {
                    throw IllegalArgumentException("Missing required 'ip' in QR payload")
                }
                if (port <= 0 || port > 65535) {
                    throw IllegalArgumentException("Invalid port '$port' in QR payload")
                }

                QrPayload(
                    ref = ref,
                    code = code,
                    ip = ip,
                    port = port
                )
            }
        }
    }
}
